from datetime import datetime

def hydrate_time(nanoseconds, tz=None):
    if nanoseconds < 0:
        raise ValueError("Negative nanoseconds are not supported")
    if tz is None:
        tz = datetime.now().tzname
    days, seconds, microseconds = divmod(nanoseconds, 1000000000)
    hours, minutes, seconds = divmod(seconds, 3600)
    seconds, microseconds = divmod(microseconds, 1000)
    return datetime

