            # CoordinateSystemVector -> float

            self._srid_map = _srid_map
            super().__init__(x, y, z)

        def validate(self):
            if not isinstance(self.x, (int, float)) or not isinstance(self.y, (int, float)): raise ValueError("x, y should be numbers")
