from typing import Tuple

def parse_version(s: str) -> Tuple[int, ...]:
    try:
        parts = s.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        return major, minor
    except ValueError:
        return ()

