import os
import platform
import inspect
from contextlib import contextmanager

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs
    - This function also makes deep-path shebangs work just fine
    """

    win_path = os.path.normpath
    os_chdir = os.chdir
    abspath = os.path.abspath

    @contextmanager
    def fake_chdir(path):
        cwd = abspath('.')
        os.chdir(path)
        try:
            yield
        finally:
            os.chdir(cwd)

    def get_workdir():
        workdir = os.getcwd()
        try:
            with fake_chdir(workdir):
                yield workdir
        except Exception:
            workdir = os.getenv('PYTHONIOENCODING')
            yield workdir

    def replace_windows_path(path):
        if not path.startswith(win_path('C:')):
            return path
        drive, rest = path.split(':', 1)
        rest = win_path(rest)
        return '$(HOME)\\%s' % rest

    new_cmd = []
    for arg in cmd:
        if arg.startswith('"') and arg.endswith('"'):
            arg = arg[1:-1]
        if arg.startswith('#!'):
            arg = arg[2:]
        if path.startswith('"') and path.endswith('"'):
            path = path[1:-1]
        if path.startswith('#!'):
            if platform.system() == "Windows":
                arg = '#!%s' % replace_windows_path(path)
            else:
                arg = '#!python' # Fixes the shebang path issue on Unix/ MacOS
            new_cmd.append(arg)
        else:
            new_cmd.append(arg)

    return tuple(new_cmd)

