def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import time
    if maxsize <= 0:
        raise ValueError("Invalid cache size")

    def memoized(func):
        import functools
        def wrapper(*args, **kwargs):
            key = (func.__name__, args, kwargs)
            if key in memoized_results:
                result = memoized_results[key]
                if timer() - result['timestamp'] >= ttl:
                    del memoized_results[key]
                    result = func(*args, **kwargs)
                return result
            result = func(*args, **kwargs)
            memoized_results[key] = {
                'result': result,
                'timestamp': timer()
            }
            if len(memoized_results) > maxsize:
                oldest_key = min(memoized_results, key=lambda k: memoized_results[k]['timestamp'])
                del memoized_results[oldest_key]
            return result
        return memoized

    memoized_results = {}
    return memoized

