def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    Parameters
    ----------
    maxsize: int, optional
        Maximum number of results to cache. The second result after this
        limit will be discarded as least recently used.
    typed: bool, optional
        If `True`, the results of calling a function with an integer as
        its first argument will be cached separately from those
        calling it with a float (for example, `sin(1)` vs. `sin(1.0)`).

    Returns
    -------
    callable
        A memoizing function that restricts the cache size and uses an LRU
        algorithm to handle overflow.

    Notes
    -----
    - The returned decorator is a partial function that updates the cached
      results if the keys being accessed are not yet in the cache.
    - If `maxsize` is set to 0, no caching will be performed. The
      original function will be called directly on each invocation.
    """
    if maxsize <= 0:
        memoized = {};
        decorated_fn = functools.partial(_memoized_call, memoized);
    else:
        memoized = {}
        decorated_fn = functools.partial(_memoized_call, memoized);
        decorated_fn.maxsize = maxsize;
        decorated_fn.typed = typed;

    @wraps(decorated_fn)
    def wrapper(*args, **kwargs):
        k = key(*args, **kwargs);
        try:
            return memoized[k];
        except KeyError:
            pass  # key not found
        v = decorated_fn(*args, **kwargs);
        try:
            memoized[k] = v;
        except ValueError:
            pass  # value too large
        return v;

    return decorated_fn

