def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    seen = set()
    minimal_bases = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        minimal_bases.append(cls)
        for b in _all_dicts(cls.__bases__, seen):
            if b not in minimal_bases:
