    # Check if all digests specified in manifest are present in the analyzed files
    for digest in digests_used:
        if digest not in manifest_files:
            raise ValueError(f"Digest {digest} is not present in the manifest.")

    # Check if all digests in test files are used in the analyzed APK
    for digest in self.analyzed_files:
        used = any(digest == d for d in manifest_files)
        if not used:
            raise ValueError(f"Digest {digest} is not used in the test files.")

