def bash_completion():
    # Retrieve the borgmatic parser
    parser = borgmatic._main._parser

    # Create a Bash completion specifications list
    bash_completion_specs = []

    # Iterate over the parser's options and arguments
    for option in parser.option_list:
        if option.dest:
            option_name = option.dest
        else:
            option_name = option.metavar
        bash_completion_specs.append("%-45s" % option_name + " # " + option.help)

    for argument in parser._arguments:
        if argument.name:
            argument_name = argument.name
        else:
            argument_name = argument.metavar
        bash_completion_specs.append("%-45s" % argument_name + " # " + argument.description)

    # Return the Bash completion specs as a string
    return '\n'.join(bash_completion_specs)

