from typing import List, Optional

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if number < 0:
        raise ValueError("Number must be non-negative")

    if padding is None:
        padding = 0

    str_number = ""
    while number > 0:
        str_number = alphabet[number % len(alphabet)] + str_number
        number //= len(alphabet)

    if len(str_number) < padding:
        str_number = "0" * (padding - len(str_number)) + str_number

    return str_number

