def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    for command in commands:
        if not isinstance(command, list):
            raise TypeError("Each command must be a list of strings.")

        output = None
        try:
            if verbose:
                print(f"Running command: {' '.join(command)}")
            result = subprocess.run(command, args=args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE if not hide_stderr else subprocess.STDOUT, env=env, text=True)
            output = result.stdout
            if result.returncode:
                raise subprocess.CalledProcessError(result.returncode, command)
        except OSError as e:
            raise OSError(f"Error running command: {e}")
        except subprocess.CalledProcessError as e:
            raise subprocess.CalledProcessError(e.returncode, command)
        except subprocess.TimeoutExpired as e:
            raise subprocess.TimeoutExpired(command, e.timeout)

        if output:
            print(" STDOUT:", output)
    print("All commands executed successfully.")

