def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    required_arguments = self.get(parser_name).required_arguments

    for arg in required_arguments:
        if arg in values_dict and values_dict[arg] is not None:
            if arg not in ["port", "host", "students"]:
                values_dict[arg] = self.get(parser_name).get(arg).convert(values_dict[arg])
            else:
                if isinstance(values_dict[arg], str):
                    try:
                        values_dict[arg] = self.get(parser_name).get(arg).convert(int(values_dict[arg]))
                    except ValueError:
                        values_dict[arg] = values_dict[arg]

