def _create_flat_dict(element, path, flat_dict):
    """Helper function to create a flatten dictionary from the nested element structure"""

    for key, value in element.items():
        new_path = f"{path}{key}."
        if isinstance(value, list):
            for idx, item in enumerate(value):
                _create_flat_dict(item, new_path, flat_dict)
        elif isinstance(value, dict):
            _create_flat_dict(value, new_path, flat_dict)
        else:
            flat_dict[new_path] = value

