import os
from pathlib import Path
import importlib
from importlib.machinery import SourceFileLoader
from configparser import ConfigParser, ConfigBuilderError

class ConfigurationManager:
    DEFAULT_SUBSTITUTIONS = {'HOME': os.path.expanduser('~')}

    def __init__(self, config_path):
        self.config_path = config_path
        self.config = None
        self.modules = {}

    def load_config(self):
        if not os.path.isfile(self.config_path):
            raise ConfigBuilderError(
                'Could not find config file: ' + self.config_path)
        loader = importlib.machinery.SourceFileLoader(self.config_path, self.config_path)
        module = loader.load_module()

        if not hasattr(module, 'config') or not isinstance(module.config, Config):
            raise ConfigBuilderError(
                'Could not load config file "{}": config files must contain '
                'a variable called "config" that is '
                'assigned to a Config object.'.format(self.config_path))
        self.config = module.config

    def inject_config(self):
        """Set the environment variable for config path, if it is undefined."""
        os.environ.setdefault('CONFIG_PATH', self.config_path)

