from os.path import join, isabs, split

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""

    if not isabs(root):
        raise TypeError('Expected absolute path "{}".'.format(root))

    path = path.replace(root, '', 1)
    if root in path:
        raise RuntimeError('The path {} is a child of the root "{}".'.format(path, root))

    return path

